-- REQUIRED IN SUPABASE SQL EDITOR: constrained local automation rules.
CREATE TABLE IF NOT EXISTS public.automation_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,name text NOT NULL,description text,trigger_type text NOT NULL,is_active boolean NOT NULL DEFAULT false,current_version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.automation_rule_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,rule_id uuid NOT NULL REFERENCES public.automation_rules(id) ON DELETE CASCADE,version integer NOT NULL,conditions jsonb NOT NULL DEFAULT '[]'::jsonb,actions jsonb NOT NULL DEFAULT '[]'::jsonb,summary text NOT NULL,created_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(rule_id,version));
CREATE TABLE IF NOT EXISTS public.automation_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,rule_id uuid NOT NULL REFERENCES public.automation_rules(id) ON DELETE CASCADE,version integer NOT NULL,prospect_id uuid REFERENCES public.prospects(id) ON DELETE SET NULL,event_key text NOT NULL,status text NOT NULL DEFAULT 'processing',condition_result jsonb NOT NULL DEFAULT '{}'::jsonb,error text,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(rule_id,event_key));
CREATE TABLE IF NOT EXISTS public.automation_action_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,execution_id uuid NOT NULL REFERENCES public.automation_executions(id) ON DELETE CASCADE,position integer NOT NULL,action_type text NOT NULL,status text NOT NULL,result jsonb,error text,attempted_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS automation_rules_org_idx ON public.automation_rules(org_id,trigger_type,is_active); CREATE INDEX IF NOT EXISTS automation_executions_org_time_idx ON public.automation_executions(org_id,started_at DESC);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['automation_rules','automation_rule_versions','automation_executions','automation_action_attempts'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_select',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=%I.org_id AND m.user_id=auth.uid()))',t||'_select',t,t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_write',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=%I.org_id AND m.user_id=auth.uid() AND m.role=''admin'')) WITH CHECK(EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=%I.org_id AND m.user_id=auth.uid() AND m.role=''admin''))',t||'_write',t,t,t); END LOOP; END $$;
